 def tensor(pos):return sum(mi*(np.dot(ri,ri)*np.eye(3)-np.outer(ri,ri)) for mi,ri in zip(masses,pos))
 IO=tensor(positions);IC=tensor(positions-com);D=M*(com@com*np.eye(3)-np.outer(com,com));max_shift_error=max(max_shift_error,float(np.max(np.abs(IO-IC-D))))
